// One event, one letter, every promoter the proposal named — the
// all-or-none reservation happened upstream, so this executor either
// delivers the letter to all of them in one send or delivers nothing.
const e = $json;
if (!e || e.type !== 'crowdrelay.gig.outreach_requested' || e.version !== 1) {
  throw new Error('gig outreach refused: unsupported event');
}
const d = e.data ?? {};
// Two letters share this event and this capability. The proposal asks a
// room for a night that does not exist yet; the ask confirms a named
// labelmate for a slot the promoter already offered on a night that is
// already held. They are not interchangeable — rendering the ask as a
// proposal announces a show that was never in question.
const isAsk = d.template_key === 'support.slot.ask.v1';
if (d.template_key !== 'gig.proposal.v1' && !isAsk) {
  throw new Error('gig outreach refused: unknown template_key ' + d.template_key);
}
const actionId = String(d.action_id || '').trim();
const venue = String(d.venue || '').trim();
const opening = String(d.opening_line || '').trim();
const reasons = Array.isArray(d.reasons)
  ? d.reasons.map((r) => String(r || '').trim()).filter(Boolean)
  : [];
const recipients = Array.isArray(d.recipients) ? d.recipients : [];
if (!actionId || !venue || !opening || !reasons.length) {
  throw new Error('gig outreach refused: payload incomplete');
}
// The address is resolved inside the sending lock upstream; a recipient
// without one means the boundary was bypassed, and that is a stop, not a
// partial send.
const emails = [];
const targetIds = [];
for (const r of recipients) {
  const em = String((r && r.contact_email) || '').trim();
  if (!em.includes('@')) {
    throw new Error('gig outreach refused: recipient without contact_email');
  }
  emails.push(em);
  targetIds.push(String((r && r.target_id) || ''));
}
if (!emails.length) throw new Error('gig outreach refused: empty recipient set');
// reasons[0] is the fact the opening line already states; the bullets carry
// the rest so the letter never repeats its first sentence as a list item.
const rest = reasons.slice(1);
const lines = [];
lines.push('Hi,');
lines.push('');
lines.push(opening);
lines.push('');
let subject;
if (isAsk) {
  // The ask's own facts, approved upstream — the act being put forward and
  // the night the slot belongs to. A missing one is an incomplete letter,
  // not something to render around.
  const support = String(d.support_act || '').trim();
  const showDate = String(d.show_date || '').trim();
  if (!support || !showDate) {
    throw new Error('gig outreach refused: an ask without a name or a date');
  }
  lines.push(
    'The night at ' + venue + ' on ' + showDate + ' is already ours, and the ' +
      'slot you offered is still open. ' + support + ' is the labelmate we ' +
      'want to put in it. This letter goes to everyone who books the room at ' +
      'once, so nobody hears about it secondhand.'
  );
  lines.push('');
  if (rest.length) {
    lines.push('Why ' + support + ' fits the slot:');
    for (const r of rest) lines.push('- ' + r.charAt(0).toUpperCase() + r.slice(1));
    lines.push('');
  }
  lines.push(
    'If ' + support + ' works for the slot, say so and they are confirmed — ' +
      'and if you would rather hold it, that answer is just as useful.'
  );
  lines.push('');
  lines.push('Best,');
  lines.push('VIRYA');
  subject = support + ' for the ' + venue + ' slot — ' + showDate;
} else {
  lines.push(
    'We are Virya, a modern metal band from Wroclaw, and we are putting ' +
      'together a night at ' + venue + '. This letter goes to everyone who ' +
      'books the room at once, so nobody hears about it secondhand.'
  );
  lines.push('');
  if (rest.length) {
    lines.push('Why we think the night works:');
    for (const r of rest) lines.push('- ' + r.charAt(0).toUpperCase() + r.slice(1));
    lines.push('');
  }
  lines.push(
    'If ' + venue + ' has a window in the coming months, tell us what the ' +
      'night needs and we will come back with a concrete offer.'
  );
  lines.push('');
  lines.push('EPK: https://virya.music/pl/epk/');
  lines.push('Music: https://virya.music/');
  lines.push('');
  lines.push('Best,');
  lines.push('VIRYA');
  subject = 'Virya x ' + venue + ' — show proposal';
}
return [{ json: {
  event_id: e.id,
  action_id: actionId,
  city_id: String(d.city_id || ''),
  venue,
  template_key: String(d.template_key),
  // The show the ask is about, when it is one — the receipt records it so
  // the ledger can trace the letter back to the slot.
  show_event_id: d.event_id ? String(d.event_id) : null,
  recipient_count: emails.length,
  recipient_target_ids: targetIds,
  SendTo: emails.join(', '),
  SendSubject: subject.slice(0, 220),
  SendBody: lines.join('\n'),
}}];

const claim = $json;
const intent = $('Validate and compose letter').first().json;
// A replay of an already-finished action is a no-op, not an error.
if (claim.disposition === 'already_succeeded') return [];
// claimed is the only disposition that may reach the provider; in_flight
// and ambiguous stay claimed upstream and never send twice.
if (claim.disposition !== 'claimed' || !claim.claim_token) {
  throw new Error('Provider execution ' + (claim.disposition || 'unclaimed') + '; fail closed to prevent duplicate external side effects');
}
return [{ json: { ...intent, claim_token: String(claim.claim_token), attempt_number: Number(claim.attempt_number || 1) } }];

const intent = $('Fail-closed claim gate').first().json;
const failed = Boolean($json.error);
const ref = $json.threadId || $json.thread_id || $json.id || null;
return [{ json: {
  action_id: intent.action_id,
  receipt_key: 'gig_outreach:' + intent.action_id + ':email',
  executor_id: $env.VIRYAOS_EXECUTOR_ID || 'virya-n8n-primary',
  status: failed ? 'failed' : 'succeeded',
  claim_token: intent.claim_token,
  provider_reference: failed ? null : (ref ? String(ref).slice(0, 240) : null),
  error_kind: failed ? 'gmail_send_failed' : null,
  metadata: {
    channel: 'email',
    event_id: intent.event_id,
    show_event_id: intent.show_event_id,
    venue: intent.venue,
    city_id: intent.city_id,
    recipient_count: intent.recipient_count,
    recipient_target_ids: intent.recipient_target_ids,
    template_key: intent.template_key,
  },
  occurred_at: new Date().toISOString(),
}}];
